using LittleLeo.Variables;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "MultiverseCubeOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/MultiverseCube Omen Data")]
public class MultiverseCubeOmenData : OmenData
{
	[Header("Multiverse Cube")]
	[SerializeField]
	private BoolReference shuffleOmenActiveBoolReference;

	public override void Initialize(OmenInstance omenInstance)
	{
		shuffleOmenActiveBoolReference.SetValue(value: true);
	}

	public override void OmenRemoved()
	{
		shuffleOmenActiveBoolReference.SetValue(value: false);
	}
}
